namespace EasyContainerManager

/// <summary>多言語UIテキストの定義と翻訳取得を行うモジュール。</summary>
module Localization =
    /// <summary>対応言語コードと表示名のペア一覧。</summary>
    let languages =
        [| "ja-JP", "日本語"
           "en-US", "English"
           "zh-CN", "简体中文"
           "zh-TW", "繁體中文"
           "ko-KR", "한국어"
           "fr-FR", "Français"
           "de-DE", "Deutsch"
           "es-ES", "Español"
           "it-IT", "Italiano"
           "pt-BR", "Português"
           "ru-RU", "Русский" |]

    /// <summary>言語コードまたは表示名を正規化された言語コードに変換する。</summary>
    let normalizeCode (value: string) =
        match languages |> Array.tryFind (fun (code, name) -> code = value || name = value) with
        | Some(code, _) -> code
        | None -> "ja-JP"

    /// <summary>言語コードに対応する表示名を返す。</summary>
    let displayName code =
        languages
        |> Array.tryFind (fun (languageCode, _) -> languageCode = code)
        |> Option.map snd
        |> Option.defaultValue "日本語"

