    /// <summary>登録されているすべての翻訳テーブルを返す。</summary>
    let private allMaps = [ versionAndInfoTranslations; monitoringTranslations; connectionTranslations; translations ]

    /// <summary>登録されているすべての翻訳キーを返す。</summary>
    let allKeys =
        allMaps
        |> List.collect (Map.toList >> List.map fst)
        |> List.distinct

    /// <summary>指定キーが全対応言語分の翻訳を持っているかを検証する。</summary>
    let hasAllTranslations (japanese: string) =
        allMaps
        |> List.tryPick (Map.tryFind japanese)
        |> Option.exists (fun values -> values.Length = languages.Length && values |> Array.forall (System.String.IsNullOrWhiteSpace >> not))

    /// <summary>指定された言語コードに応じて日本語キーまたは英語から翻訳済み文字列を返す。</summary>
    let translate languageCode japanese english =
        let index = languages |> Array.tryFindIndex (fun (code, _) -> code = languageCode) |> Option.defaultValue 1
        if index = 0 then japanese
        else
            allMaps
            |> List.tryPick (Map.tryFind japanese)
            |> Option.bind (fun values -> if index < values.Length then Some values.[index] else None)
            |> Option.defaultValue english

    /// <summary>辞書に登録されたキーから指定言語の翻訳文字列を取得する（未登録時はキーをそのまま返す）。</summary>
    let translateKey languageCode (key: string) =
        let index = languages |> Array.tryFindIndex (fun (code, _) -> code = languageCode) |> Option.defaultValue 1
        allMaps
        |> List.tryPick (Map.tryFind key)
        |> Option.bind (fun values -> if index < values.Length then Some values.[index] else None)
        |> Option.defaultValue key